# application.yml
p120:
  salida: "S151/FILE/CONCENTRA/{fecha}."   # W-ETIQ-SALDOS
  fecha-en-nombre: yyMMdd                  # PANO/PMES/PDIA son PIC 9(02)

// ---------------------------------------------------------------------------
/** FECHA-BASE (Cronos-2000): siglo, año, mes y día en cuatro campos 9(02) COMP. */
public record FechaBase(int siglo, int anio, int mes, int dia) {

    public LocalDate toLocalDate() {
        return LocalDate.of(siglo * 100 + anio, mes, dia);   // AA-FBASE1 * 100 + AA-FBASE2
    }
}

@ConfigurationProperties("p120")
public record P120Properties(String salida, String fechaEnNombre) {
    public String archivo(LocalDate fecha) {
        return salida.replace("{fecha}", fecha.format(DateTimeFormatter.ofPattern(fechaEnNombre)));
    }
}

# application.yml  (CSI-SIGLAS y NOMB-CSIS dejan de estar compiladas)
s151:
  csis:
    1:  { siglas: HER, nombre: "C.S.I. HERMOSILLO" }
    4:  { siglas: MON, nombre: "C.S.I. MONTERREY" }
    6:  { siglas: LEO, nombre: "C.S.I. CENTRO BAJIO" }
    7:  { siglas: VER, nombre: "C.S.I. VERACRUZ" }
    9:  { siglas: CEN, nombre: "C.S.I. MORELOS" }
    10: { siglas: VDM, nombre: "C.S.I. VALLE DE MEX." }

// ---------------------------------------------------------------------------
@ConfigurationProperties("s151")
public record CsiCatalogo(Map<Integer, Csi> csis) {
    public record Csi(String siglas, String nombre) {}

    /** NOMBRE-CSI(77-CSI): en COBOL un índice 2, 3, 5 u 8 da espacios y uno mayor que 10 sale del arreglo. */
    public Csi de(int csi) {
        Csi c = csis.get(csi);
        if (c == null) throw new IllegalStateException("CSI sin catálogo: " + csi);
        return c;
    }
}

/** W-REG-SALDOS: un buffer de 90 bytes; la vista la decide el primer campo (CVES). */
public sealed interface ConcentraRecord
        permits ConcentraRecord.Header, ConcentraRecord.Sucursal,
                ConcentraRecord.Cliente, ConcentraRecord.Global, ConcentraRecord.Trailer {

    /** CVES X(02) = "HR". */
    record Header(int csiOrigen, int sistema, LocalDate fechaProceso,
                  int diaCreacion, int horaCreacion) implements ConcentraRecord {}

    /** W-REG-SUCURSAL. Saldos 9(18)V99 COMP: BigDecimal escala 2. */
    record Sucursal(int sistema, int sucursal, int moneda,
                    BigDecimal saldoAnterior, BigDecimal saldoActual,
                    LocalDate fecha) implements ConcentraRecord {}

    /** W-REG-CLIENTE, W-REG-GLOBALES y W-TRAILER-SDOS: definidos en el layout, P120 no los escribe. */
    record Cliente(int sistema, int sucursal, int moneda, long cuentas, int institucion,
                   String nombre, BigDecimal saldoAnterior, BigDecimal saldoActual,
                   LocalDate fecha) implements ConcentraRecord {}
    record Global(int sistema, int moneda, BigDecimal saldoAnterior,
                  BigDecimal saldoActual, LocalDate fecha) implements ConcentraRecord {}
    record Trailer(int sistema, long registros) implements ConcentraRecord {}
}

/** Serializa al layout binario original para los consumidores del lote. */
public final class ConcentraCodec implements LineAggregator<ConcentraRecord> { /* COMP según DASDL */ }

@Configuration
@EnableConfigurationProperties({P120Properties.class, CsiCatalogo.class})
public class ConcentracionSaldosJobConfig {

    /** 000-RAIZ: secuencia fija de PERFORM y STOP RUN. */
    @Bean
    Job concentracionSaldos(JobRepository repo,
                            Step control,             // 1000-ABRE: control, header, apertura de salidas
                            Step saldosSucursal,      // 2000-PROCESO UNTIL 77-EOF = 1
                            Step conceptos,           // 3000-CONCEPTOS UNTIL 77-EOF = 2
                            Step totalesSar,          // 4000-TOT-B07TOTSDO + 5000-TOT-B08GLOSAR
                            Step reportesSar) {       // 6000-IMPRIME-SAR + 8000-IMPRIME-SAR-TESORERIA
        return new JobBuilder("S151P120", repo)
                .start(control)
                .next(saldosSucursal)
                .next(conceptos)
                .next(totalesSar)
                .next(reportesSar)
                .build();
        // 7000-CIERRA (CLOSE SALDOS WITH LOCK) lo hace el ItemWriter al cerrar su step.
    }
}

@Component
@RequiredArgsConstructor
public class ControlSaldosTasklet implements Tasklet {

    private final ControlSaldoRepository control;   // registro B92 de S151BD02ADSALDO

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        var b92 = control.findControl()
                .orElseThrow(() -> new ProcesoAbortadoException(
                        "S151/P120 NO EXISTE REG DE FECHAS"));        // SET MYSELF(STATUS) TO -1

        var ec = ctx.getStepContext().getStepExecution().getJobExecution().getExecutionContext();
        ec.putInt("csi", b92.csi());                                    // 77-CSI
        ec.put("fechaBase", b92.fecha().toLocalDate());                 // FECHA-BASE
        return RepeatStatus.FINISHED;
    }
}

/** El header se escribe desde el callback del writer al abrir CONCENTRA. */
@Bean @StepScope
FlatFileHeaderCallback headerConcentra(@Value("#{jobExecutionContext['csi']}") int csi,
                                       @Value("#{jobExecutionContext['fechaBase']}") LocalDate f,
                                       ConcentraCodec codec) {
    return w -> w.write(codec.header(new ConcentraRecord.Header(csi, 0, f, 0, 0)));   // CVES "HR"
}

/** 2100-CARGA-DATOS + 2200-CARGA-TAB: una fila de B02SDOSUC produce hasta 20 registros. */
@Component
@StepScope
@RequiredArgsConstructor
public class SucursalSistemaProcessor implements ItemProcessor<SaldoSucursal, List<ConcentraRecord.Sucursal>> {

    private static final int MAX_SISTEMAS = 20;            // OCCURS 20
    private final ListadoConcentracion listado;            // 9000-REPORTE

    @Override
    public List<ConcentraRecord.Sucursal> process(SaldoSucursal b02) {
        if (b02.sistemas().size() > MAX_SISTEMAS) {
            throw new IllegalStateException("Sucursal con más de 20 sistemas: " + b02.numero());
        }
        var salida = new ArrayList<ConcentraRecord.Sucursal>();
        for (var s : b02.sistemas()) {
            if (s.sistema() <= 0) continue;                // IF B02-SUC-SISTEMA (I) > 0
            var r = new ConcentraRecord.Sucursal(s.sistema(), b02.numero(), b02.moneda(),
                                                 s.anterior(), s.actual(), null);
            listado.detalle(r);
            salida.add(r);
        }
        return salida;
    }
}
// Lector: RepositoryItemReader sobre S151B02SDOSUC (FIND NEXT). NOTFOUND = fin del step;
// cualquier otra DataAccessException deja el step en FAILED (SET MYSELF(STATUS) TO -1).

/** 3100-REPORTE-CNC. TAB-SDO-CNC(1..7) PIC 9(16)V99 COMP. */
@Component
@StepScope
public class ConceptosProcessor implements ItemProcessor<SaldoConcepto, RenglonConcepto> {

    private final BigDecimal[] acumulado = Stream.generate(() -> BigDecimal.ZERO.setScale(2))
            .limit(7).toArray(BigDecimal[]::new);

    @Override
    public RenglonConcepto process(SaldoConcepto b05) {
        BigDecimal[] v = { b05.cobro(), b05.saldoCaja(), b05.imss(),
                           b05.aduana(), b05.concentracionBanxico(), b05.retirosBanxico() };
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (int i = 0; i < 6; i++) {
            acumulado[i] = acumulado[i].add(v[i]);
            acumulado[6] = acumulado[6].add(v[i]);       // TAB-SDO-CNC(7)
            total = total.add(v[i]);                       // 77-VAR S9(16)V99: suma exacta
        }
        return new RenglonConcepto(b05.sucursal(), v, total);
    }

    @AfterStep
    ExitStatus totales(StepExecution se) {                 // 3200-TOTALES-CNC
        se.getExecutionContext().put("totalesCnc", acumulado);
        return se.getExitStatus();
    }
}

/** 9300-DETALLE. */
public RenglonConcentracion detalle(ConcentraRecord.Sucursal r) {
    String moneda = r.moneda() == 1 ? "NAC" : "EXT";               // cualquier otra moneda es EXT
    BigDecimal variacion = r.saldoAnterior().subtract(r.saldoActual()); // COMPUTE 77-VAR = SANT - SACT
    return new RenglonConcentracion(r.sucursal(), moneda, r.sistema(),
                                    r.saldoAnterior(), r.saldoActual(), variacion);
}

/** 4000-TOT-B07TOTSDO: posiciones fijas del arreglo B07-S333 (CSI activos). */
@Component
@RequiredArgsConstructor
public class TotalesSarTasklet implements Tasklet {

    private final TotalSaldoSarRepository b07;
    private final P120Properties props;   // p120.posiciones-csi: [1, 4, 6, 7, 9, 10]

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        ImportesSar ultimo = ImportesSar.CERO;
        for (var reg : b07.findAllInOrder()) {
            // COMPUTE 77-IMPAB = ... reemplaza el valor en cada registro: solo cuenta el último.
            ultimo = new ImportesSar(suma(reg.impAb()), suma(reg.impOr()), suma(reg.impFv()));
        }
        ctx.getStepContext().getStepExecution().getJobExecution()
           .getExecutionContext().put("importesSar", ultimo);
        return RepeatStatus.FINISHED;
    }

    /** 77-IMPAB, 77-IMPOR, 77-IMPFV son PIC 9(20) COMP sin decimales. */
    private BigDecimal suma(BigDecimal[] arr) {
        return props.posicionesCsi().stream().map(p -> arr[p - 1])
                .reduce(BigDecimal.ZERO, BigDecimal::add)
                .setScale(0, RoundingMode.DOWN);
    }
}

/** 5000-TOT-B08GLOSAR. Acumuladores 9(18)V99 COMP. */
for (var g : b08.findAllInOrder()) {
    sar.fecha(g.fecha());
    sar.obligatoriasImss(g.oblImss());  sar.voluntariasImss(g.volImss());
    sar.obligatoriasIsste(g.oblIste()); sar.voluntariasIsste(g.volIste());
    sar.inflacionImss(g.infImss());     sar.interesesImss(g.intImss());
    sar.inflacionIsste(g.infIste());    sar.interesesIsste(g.intIste());
    sar.obligatoriasInfo(g.oblInfo());  sar.voluntariasInfo(g.volInfo());
    sar.provisionalesInfo(g.iprInfo()); sar.definitivosInfo(g.ideInfo());
    sar.anteriorImss(g.antImss());
    sar.anteriorIsste(g.antIste());
    if (props.compatibilidadSarLegacy()) {
        sar.anteriorIsste(g.antInfo());   // línea 1198: ADD B08-GSAR-ANT-INFO TO 77-ANT-ISTE
    } else {
        sar.anteriorInfo(g.antInfo());    // corrección: decisión de negocio pendiente
    }
    sar.actualImss(g.actImss()); sar.actualIsste(g.actIste()); sar.actualInfo(g.actInfo());
}
